coding_challenges.starter_code:
secret = 42
guesses = 0

while True:
    guess = int(input("Guess the number (1-100): "))
    guesses += 1

    if guess == secret:
        print(f"Correct! You got it in {guesses} guesses.")
        break
    elif guess > secret:
        print("Too high!")
    else:
        print("Too low!")

